#include <IRremote.h>

const uint8_t IR_PIN = 7; // Пин, к которому подключён ИК-приёмник
IRrecv irrecv(IR_PIN); // Создаём объект приёмника
decode_results results; // Объект для хранения результатов декодирования

void setup() {
  Serial.begin(9600);
  irrecv.enableIRIn(); // Включаем приём
}

void loop() {
  if (irrecv.decode(&results)) {
    Serial.println(results.value); // Выводим полученный код
    irrecv.resume(); // Ждём следующего сигнала
  }
}
